// CSD_RATIONALE_BEGIN
// Root-cause analysis of the attempt 73/74 regression (40.8% → 2-10%):
// Comparing attempt 1 (40.8%) to attempts 73–74 shows that the ONLY functionally
// significant change between attempt 1 and attempt 73 was the guidance text.
// Attempt 73 introduced complex multi-example guidance instructing the model to
// wrap EACH intermediate calculation in << >>, which causes the model to generate
// 9+ short partial-expression spans and the LAST span (the one extracted as the
// answer) is just the last intermediate term, not the full combined expression.
//
// Observed failure pattern in rollouts:
//   "The final answer is <<n - n>> - <<n1 * w1>> - <<n2 * w2>> - <<n3 * w3>>."
//   → Extracted: n3 * w3   ← WRONG
//   → Correct:   n - n1*w1 - n2*w2 - n3*w3
//
// The model splits a combined expression across multiple spans with operators
// between them, rather than putting the complete expression in ONE span.
//
// This attempt:
// 1. Returns to attempt 1's structure (free generation + constrained spans) which
//    verified at 40.8%.
// 2. Fixes the required RenderedEndsWith delimiter detection (replacing `next == "<<"`).
// 3. Uses targeted guidance that DIRECTLY addresses the split-span failure mode:
//    explicitly shows WRONG vs RIGHT examples to teach the model not to split.
// 4. Uses CloseConstrainedSpan (immediate) when IsCompletePrefix holds.
// 5. Uses CloseSpanWithinBudget as safety net when inside a span near budget end.
// 6. Uses AdaptiveConstrainedStep with validTokenGroups for constrained tokens.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span, UnconstrainedStep, non-EOS, RenderedEndsWith triggers:
//     EnterObservedConstrainedSpan sets currentConstrainedOut := [].
//     parser.IsValidPrefix([]) holds by method precondition `parser.IsValidPrefix([])`. ✓
//   Outside-span, RenderedEndsWith does not trigger or next == eosToken:
//     insideConstrainedOut remains false; implication vacuously true. ✓
//
//   Inside-span, CloseConstrainedSpan path:
//     Guarded by `parser.IsCompletePrefix(currentConstrainedOut)` which implies
//     `parser.IsValidPrefix(currentConstrainedOut)` (invariant precondition).
//     Helper sets insideConstrainedOut := false → implication vacuously true;
//     currentConstrainedOut := [] by postcondition. ✓
//
//   Inside-span, CloseSpanWithinBudget path:
//     Helper postcondition directly guarantees
//     `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`. ✓
//
//   Inside-span, AdaptiveConstrainedStep + AppendConstrainedToken path:
//     AdaptiveConstrainedStep hard-masks to parser-valid next tokens.
//     AppendConstrainedToken postcondition: if next is parser-valid at
//     currentConstrainedOut, then parser.IsValidPrefix(currentConstrainedOut + [next]). ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: generated = generatedPrefix, steps = 0. Trivially holds. ✓
//
//   UnconstrainedStep (EOS): steps += 1, generated unchanged.
//     |generated| <= |generatedPrefix| + steps_new. ✓
//   UnconstrainedStep (non-EOS): steps += 1, generated grows by exactly 1 token.
//     |generated|_new = |generated|_old + 1 <= |generatedPrefix| + steps_new. ✓
//
//   CloseConstrainedSpan: steps += 1, generated grows by at most 1 token (">>").
//     |generated|_new <= |generated|_old + 1 <= |generatedPrefix| + steps_new. ✓
//
//   CloseSpanWithinBudget (closeBudget = maxSteps - steps):
//     Helper postcondition: |cg| <= |generated| + closeBudget = |generated| + (maxSteps - steps).
//     After steps := maxSteps: |generated| <= |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
//
//   AdaptiveConstrainedStep + AppendConstrainedToken:
//     steps += 1 before append; AppendConstrainedToken appends exactly 1 token.
//     |generated|_new = |generated|_old + 1 <= |generatedPrefix| + steps_new. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. CRITICAL RULE: Never write operations between separate << >> spans. WRONG: <<n1*p1>> + <<n2*p2>>. RIGHT: <<n1*p1 + n2*p2>>. Each << >> must be a COMPLETE self-contained expression. The LAST << >> span in your answer is extracted as the final answer, so make it the full combined formula.");

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := eg;
        insideConstrainedOut := ei;
        currentConstrainedOut := ec;
      }
    }
  } else {
    // Inside a constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Span has a complete parse: close it immediately.
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 5 {
      // Span not yet complete but budget is almost exhausted: use budget-bounded close.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Normal inside-span constrained generation step.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

